INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w02', 'lesson', 'c1w02', 0, '{"id":"c1w02","course":1,"week":"02","title":"Paesi e nazionalità","subtitle":"Countries & nationalities","topics":["essere","adjective agreement","numbers 0–20"],"italian":"Sono britannico, ma vivo a Londra.","english":"I’m British, but I live in London.","prompt":"Complete: Maria è italian__.","answer":"italiana","canDo":"I can say where I am from and describe nationality."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w03', 'lesson', 'c1w03', 1, '{"id":"c1w03","course":1,"week":"03","title":"Informazioni personali","subtitle":"Personal information","topics":["avere","stare","numbers 20–100"],"italian":"Ho ventidue anni e sto molto bene.","english":"I’m twenty-two years old and I’m very well.","prompt":"Translate: I am 25 years old.","answer":"Ho venticinque anni.","canDo":"I can exchange age, health and contact details."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w04', 'lesson', 'c1w04', 2, '{"id":"c1w04","course":1,"week":"04","title":"Lavoro e professioni","subtitle":"Jobs & professions","topics":["articles","fare","question words"],"italian":"Faccio l’ingegnere in un’azienda internazionale.","english":"I work as an engineer in an international company.","prompt":"Choose: ___ psicologo (un / uno).","answer":"uno psicologo","canDo":"I can ask and answer simple questions about work."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w05', 'lesson', 'c1w05', 3, '{"id":"c1w05","course":1,"week":"05","title":"Al bar e al ristorante","subtitle":"At the bar & restaurant","topics":["ordering","polite requests","food"],"italian":"Vorrei un caffè e un cornetto, per favore.","english":"I’d like a coffee and a croissant, please.","prompt":"How do you ask for the bill?","answer":"Il conto, per favore.","canDo":"I can order and pay in a café or restaurant."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w06', 'lesson', 'c1w06', 4, '{"id":"c1w06","course":1,"week":"06","title":"Il tempo libero","subtitle":"Free time","topics":["present tense","frequency","hobbies"],"italian":"Nel tempo libero leggo e vado spesso al cinema.","english":"In my free time I read and often go to the cinema.","prompt":"Put in order: spesso / nuoto / io.","answer":"Io nuoto spesso.","canDo":"I can describe hobbies and how often I do them."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w07', 'lesson', 'c1w07', 5, '{"id":"c1w07","course":1,"week":"07","title":"Piacere e l’ora","subtitle":"Likes & telling the time","topics":["piacere","agreement","time"],"italian":"Mi piace cucinare, ma non mi piacciono i dolci.","english":"I like cooking, but I don’t like sweets.","prompt":"Choose: Mi piace / piacciono le città italiane.","answer":"Mi piacciono le città italiane.","canDo":"I can express likes and tell the time."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w08', 'lesson', 'c1w08', 6, '{"id":"c1w08","course":1,"week":"08","title":"In albergo","subtitle":"Hotel & prepositions","topics":["prepositions","c’è / ci sono","potere"],"italian":"C’è una camera libera al secondo piano?","english":"Is there a free room on the second floor?","prompt":"Combine: in + la camera.","answer":"nella camera","canDo":"I can book a simple hotel room and describe facilities."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w09', 'lesson', 'c1w09', 7, '{"id":"c1w09","course":1,"week":"09","title":"Primo ripasso","subtitle":"First revision","topics":["articles","verbs","professions"],"italian":"La cuoca lavora in cucina e prepara piatti deliziosi.","english":"The cook works in the kitchen and prepares delicious dishes.","prompt":"What is the feminine of cuoco?","answer":"cuoca","canDo":"I can combine early A1 grammar in short conversations."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w11', 'lesson', 'c1w11', 8, '{"id":"c1w11","course":1,"week":"11","title":"La giornata speciale","subtitle":"Routines, possessives & wishes","topics":["reflexives","possessives","fare"],"italian":"La mattina mi sveglio presto e faccio colazione.","english":"In the morning I wake up early and have breakfast.","prompt":"Complete: Questa è ___ sorella. (my)","answer":"mia sorella","canDo":"I can describe a routine, possessions and celebrations."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w12', 'lesson', 'c1w12', 9, '{"id":"c1w12","course":1,"week":"12","title":"In città","subtitle":"Town & modal verbs","topics":["potere / dovere / volere","partitive","ci"],"italian":"Devo andare in farmacia; sai dov’è?","english":"I have to go to the pharmacy; do you know where it is?","prompt":"Choose: Conosco / So parlare italiano.","answer":"So parlare italiano.","canDo":"I can ask for directions and express wants, duties and abilities."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w13', 'lesson', 'c1w13', 10, '{"id":"c1w13","course":1,"week":"13","title":"Il passato","subtitle":"Passato prossimo","topics":["avere vs essere","participles","agreement"],"italian":"Ieri sono andato al mercato e ho comprato del pane.","english":"Yesterday I went to the market and bought some bread.","prompt":"Complete: Marta è ___ a casa. (return)","answer":"Marta è tornata a casa.","canDo":"I can report a short sequence of completed past events."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w13b', 'lesson', 'c1w13b', 11, '{"id":"c1w13b","course":1,"week":"13b","title":"Sessione di ripasso","subtitle":"Revision workshop","topics":["mixed grammar","reading","games"],"italian":"Ripassiamo gli articoli, i verbi e le preposizioni.","english":"Let’s review articles, verbs and prepositions.","prompt":"Complete: Vado ___ cinema.","answer":"Vado al cinema.","canDo":"I can switch between mixed A1 grammar under time pressure."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w14', 'lesson', 'c1w14', 12, '{"id":"c1w14","course":1,"week":"14","title":"I pronomi diretti","subtitle":"Direct object pronouns","topics":["lo / la / li / le","pronoun position","verbs"],"italian":"Compri le mele? Sì, le compro.","english":"Are you buying the apples? Yes, I’m buying them.","prompt":"Replace: Mangio la pizza.","answer":"La mangio.","canDo":"I can avoid repetition with direct object pronouns."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w15', 'lesson', 'c1w15', 13, '{"id":"c1w15","course":1,"week":"15","title":"Al supermercato","subtitle":"Food shopping","topics":["partitive","quantities","shopping"],"italian":"Vorrei due etti di prosciutto e del formaggio.","english":"I’d like two hundred grams of ham and some cheese.","prompt":"Choose: del / della pasta.","answer":"della pasta","canDo":"I can shop for food using quantities and partitives."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w16', 'lesson', 'c1w16', 14, '{"id":"c1w16","course":1,"week":"16","title":"La famiglia","subtitle":"Family","topics":["possessives","descriptions","family"],"italian":"Mio fratello è alto e molto simpatico.","english":"My brother is tall and very nice.","prompt":"Why no article in ‘mia madre’?","answer":"Singular, unmodified close family members normally omit the article.","canDo":"I can describe my family and relationships."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w17', 'lesson', 'c1w17', 15, '{"id":"c1w17","course":1,"week":"17","title":"Passaporto e identità","subtitle":"Identity details","topics":["personal details","nationalities","forms"],"italian":"Sono nato a Londra il dodici maggio.","english":"I was born in London on the twelfth of May.","prompt":"Ask: Where were you born?","answer":"Dove sei nato / nata?","canDo":"I can give identity details and complete a simple form."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w18', 'lesson', 'c1w18', 16, '{"id":"c1w18","course":1,"week":"18","title":"Descrivere e proporre","subtitle":"Revision & proposals","topics":["appearance","possessives","proposals","past"],"italian":"Perché non andiamo al museo domenica?","english":"Why don’t we go to the museum on Sunday?","prompt":"Accept enthusiastically.","answer":"Sì, volentieri!","canDo":"I can describe people and make simple proposals."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w19', 'lesson', 'c1w19', 17, '{"id":"c1w19","course":1,"week":"19","title":"La routine quotidiana","subtitle":"Daily routine","topics":["reflexive verbs","time","frequency"],"italian":"Di solito mi alzo alle sette e mezza.","english":"I usually get up at half past seven.","prompt":"Conjugate svegliarsi for noi.","answer":"noi ci svegliamo","canDo":"I can describe my daily routine with times and frequency."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c1w20', 'lesson', 'c1w20', 18, '{"id":"c1w20","course":1,"week":"20","title":"La casa","subtitle":"Estate & property","topics":["rooms","c’è / ci sono","prepositions","renting"],"italian":"Nell’appartamento ci sono due camere e un balcone.","english":"There are two bedrooms and a balcony in the flat.","prompt":"Ask whether bills are included.","answer":"Le spese sono incluse?","canDo":"I can understand a rental advert and ask key questions."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w01', 'lesson', 'c2w01', 19, '{"id":"c2w01","course":2,"week":"01","title":"Presentazioni","subtitle":"Introductions revisited","topics":["essere","regular verbs","piacere","reflexives"],"italian":"Mi chiamo Guglielmo, vivo a Londra e studio italiano.","english":"My name is Guglielmo, I live in London and I study Italian.","prompt":"Introduce yourself in three clauses.","answer":"Mi chiamo…, vivo a… e studio / lavoro…","canDo":"I can give a one-minute personal introduction."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w02', 'lesson', 'c2w02', 20, '{"id":"c2w02","course":2,"week":"02","title":"La famiglia","subtitle":"Possessives & family","topics":["possessives","relationships","agreement"],"italian":"I miei genitori abitano vicino ai miei nonni.","english":"My parents live near my grandparents.","prompt":"Complete: ___ cugine sono italiane. (our)","answer":"Le nostre cugine","canDo":"I can describe my family using accurate possessives."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w03', 'lesson', 'c2w03', 21, '{"id":"c2w03","course":2,"week":"03","title":"Il mondo del lavoro","subtitle":"Jobs & workplaces","topics":["articles","plurals","workplaces","reading"],"italian":"L’infermiera lavora in ospedale e aiuta i pazienti.","english":"The nurse works in a hospital and helps patients.","prompt":"Plural: il giornalista.","answer":"i giornalisti","canDo":"I can understand and discuss familiar jobs and workplaces."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w04', 'lesson', 'c2w04', 22, '{"id":"c2w04","course":2,"week":"04","title":"Routine e corpo umano","subtitle":"Daily routine & the body","topics":["reflexives","body","irregular plurals","song"],"italian":"Mi lavo le mani e poi mi pettino i capelli.","english":"I wash my hands and then comb my hair.","prompt":"Plural of il braccio?","answer":"le braccia","canDo":"I can describe a routine and basic parts of the body."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w05', 'lesson', 'c2w05', 23, '{"id":"c2w05","course":2,"week":"05","title":"In città","subtitle":"Town & reflexive verbs","topics":["directions","reflexives","opposites"],"italian":"La banca è di fronte alla farmacia.","english":"The bank is opposite the pharmacy.","prompt":"Translate: next to the station.","answer":"accanto alla stazione","canDo":"I can locate places and follow simple directions."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w06', 'lesson', 'c2w06', 24, '{"id":"c2w06","course":2,"week":"06","title":"Al bar e al ristorante","subtitle":"Ordering with confidence","topics":["ordering","articles","verbs","quick test"],"italian":"Per me gli gnocchi; da bere, dell’acqua frizzante.","english":"Gnocchi for me; sparkling water to drink.","prompt":"Politely order a starter.","answer":"Come antipasto, vorrei…","canDo":"I can manage a complete restaurant interaction."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w07', 'lesson', 'c2w07', 25, '{"id":"c2w07","course":2,"week":"07","title":"Preposizioni","subtitle":"Grammar revision","topics":["simple prepositions","articulated prepositions","Tutti Frutti"],"italian":"Vado in biblioteca, ma studio nella Biblioteca Centrale.","english":"I go to the library, but I study in the Central Library.","prompt":"Combine: su + gli scaffali.","answer":"sugli scaffali","canDo":"I can select simple or articulated prepositions accurately."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w08', 'lesson', 'c2w08', 26, '{"id":"c2w08","course":2,"week":"08","title":"Cibo e vestiti","subtitle":"Food, clothes & colours","topics":["food","clothes","colours","agreement"],"italian":"Cerco una camicia bianca e dei pantaloni neri.","english":"I’m looking for a white shirt and black trousers.","prompt":"Make plural: la scarpa rossa.","answer":"le scarpe rosse","canDo":"I can shop for food and clothes using colour agreement."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('lesson:c2w09', 'lesson', 'c2w09', 27, '{"id":"c2w09","course":2,"week":"09","title":"Albergo e progetti","subtitle":"Hotel problems & weekend plans","topics":["articulated prepositions","hotel","invitations","formal Lei"],"italian":"La card non funziona. Mi può aiutare, per favore?","english":"The key card doesn’t work. Can you help me, please?","prompt":"Suggest visiting a museum.","answer":"Ti va di visitare un museo? / Perché non visitiamo un museo?","canDo":"I can solve a hotel problem and negotiate weekend plans."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:morning', 'reading', NULL, 0, '{"id":"morning","level":"A1","title":"Una mattina a Londra","theme":"Routine","sentences":[["Ogni mattina Guglielmo si sveglia alle sette.","Every morning Guglielmo wakes up at seven."],["Fa una doccia, si veste e prepara un caffè forte.","He takes a shower, gets dressed and makes a strong coffee."],["Prima di uscire controlla il tempo e prende l’ombrello.","Before going out, he checks the weather and takes his umbrella."],["Va all’università in metropolitana e durante il viaggio ripassa dieci parole italiane.","He goes to university by Underground and reviews ten Italian words during the journey."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:bologna', 'reading', NULL, 1, '{"id":"bologna","level":"A1+","title":"Un fine settimana a Bologna","theme":"Past tense","sentences":[["Sabato scorso sono andato a Bologna con due amici.","Last Saturday I went to Bologna with two friends."],["Abbiamo visitato il centro e abbiamo mangiato le tagliatelle al ragù.","We visited the centre and ate tagliatelle with ragù."],["Nel pomeriggio ha piovuto, quindi siamo entrati in un museo.","In the afternoon it rained, so we went into a museum."],["La sera eravamo stanchi, ma molto contenti della giornata.","In the evening we were tired, but very happy with the day."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:restaurant', 'reading', NULL, 2, '{"id":"restaurant","level":"A1","title":"Una cena semplice","theme":"Restaurant","sentences":[["Al ristorante chiediamo un tavolo per due vicino alla finestra.","At the restaurant we ask for a table for two near the window."],["Come antipasto prendiamo delle olive e del pane.","As a starter we have some olives and some bread."],["Io ordino la pasta, mentre la mia amica preferisce il pesce.","I order pasta, while my friend prefers fish."],["Alla fine chiediamo il conto e lasciamo una piccola mancia.","At the end we ask for the bill and leave a small tip."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:flat', 'reading', NULL, 3, '{"id":"flat","level":"A1+","title":"L’appartamento ideale","theme":"Home","sentences":[["Cerco un appartamento luminoso non lontano dal centro.","I’m looking for a bright flat not far from the centre."],["Deve avere una camera, un soggiorno e una cucina moderna.","It must have a bedroom, a living room and a modern kitchen."],["Vorrei anche un balcone perché mi piace fare colazione fuori.","I’d also like a balcony because I enjoy having breakfast outside."],["Prima di firmare il contratto chiedo se le spese sono incluse.","Before signing the contract, I ask whether the bills are included."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:hotel', 'reading', NULL, 4, '{"id":"hotel","level":"A1+","title":"Un problema in albergo","theme":"Hotel","sentences":[["Arrivo in albergo alle sei, ma la mia prenotazione non è nel sistema.","I arrive at the hotel at six, but my booking isn’t in the system."],["Spiego il problema con calma e mostro l’e-mail di conferma.","I calmly explain the problem and show the confirmation email."],["La receptionist controlla di nuovo e trova una camera al terzo piano.","The receptionist checks again and finds a room on the third floor."],["La ringrazio e le chiedo a che ora servono la colazione.","I thank her and ask what time they serve breakfast."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar:1', 'grammar', NULL, 0, '{"title":"Articles","rule":"Choose by sound, gender and number — not only by the first letter.","example":"lo studente · gli studenti · un’amica","translation":"the student · the students · a female friend"}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar:2', 'grammar', NULL, 1, '{"title":"Present tense","rule":"Drop -are/-ere/-ire and add the ending for the subject.","example":"parlo · prendi · dormiamo","translation":"I speak · you take · we sleep"}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar:3', 'grammar', NULL, 2, '{"title":"Piacere","rule":"The thing liked controls piace/piacciono; the person is introduced by mi/ti/gli/le/ci/vi.","example":"Mi piace il mare. Mi piacciono le città.","translation":"I like the sea. I like cities."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar:4', 'grammar', NULL, 3, '{"title":"Reflexives","rule":"Keep the reflexive pronoun with the conjugated verb.","example":"Mi sveglio. Ci prepariamo.","translation":"I wake up. We get ready."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar:5', 'grammar', NULL, 4, '{"title":"Prepositions","rule":"Di, a, da, in and su combine with definite articles.","example":"al museo · nella camera · sugli scaffali","translation":"at/to the museum · in the room · on the shelves"}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar:6', 'grammar', NULL, 5, '{"title":"Passato prossimo","rule":"Present of avere/essere + past participle; agree after essere.","example":"Ho mangiato. Siamo arrivati.","translation":"I ate. We arrived."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar:7', 'grammar', NULL, 6, '{"title":"Direct pronouns","rule":"Place lo/la/li/le before the conjugated verb.","example":"La vedo. Li compro.","translation":"I see her/it. I buy them."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar:8', 'grammar', NULL, 7, '{"title":"Possessives","rule":"Possessives agree with the possessed thing, not the owner.","example":"il mio libro · le nostre case","translation":"my book · our houses"}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('grammar:9', 'grammar', NULL, 8, '{"title":"C’è / ci sono","rule":"Use c’è for one thing and ci sono for more than one.","example":"C’è un balcone. Ci sono due camere.","translation":"There is a balcony. There are two bedrooms."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('legacy_quiz:1', 'legacy_quiz', NULL, 0, '{"q":"Choose the correct sentence.","options":["Mi piace le città.","Mi piacciono le città.","Io piaccio le città."],"a":1,"note":"Piacciono agrees with the plural thing liked: le città."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('legacy_quiz:2', 'legacy_quiz', NULL, 1, '{"q":"Complete: Vado ___ Teatro Verdi.","options":["a","al","nel"],"a":1,"note":"A named/specific theatre takes the article: a + il = al."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('legacy_quiz:3', 'legacy_quiz', NULL, 2, '{"q":"Replace the object: Compro le mele.","options":["Le compro.","Li compro.","La compro."],"a":0,"note":"Le replaces a feminine plural noun."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('legacy_quiz:4', 'legacy_quiz', NULL, 3, '{"q":"Which sentence means ‘I got up at eight’ ?","options":["Mi alzo alle otto.","Mi sono alzato alle otto.","Ho alzato alle otto."],"a":1,"note":"A reflexive verb uses essere in the passato prossimo."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('legacy_quiz:5', 'legacy_quiz', NULL, 4, '{"q":"Choose the correct family phrase.","options":["la mia madre","mia madre","il mio madre"],"a":1,"note":"A singular, unmodified close family member normally omits the article."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('legacy_quiz:6', 'legacy_quiz', NULL, 5, '{"q":"Complete: Vorrei ___ acqua naturale.","options":["del","dell’","della"],"a":1,"note":"Acqua is feminine and begins with a vowel: dell’acqua."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('legacy_quiz:7', 'legacy_quiz', NULL, 6, '{"q":"Which is the polite hotel request?","options":["Dammi una camera.","Mi può aiutare?","Tu aiutami."],"a":1,"note":"Mi può aiutare? uses formal Lei."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('legacy_quiz:8', 'legacy_quiz', NULL, 7, '{"q":"Choose the correct colour agreement.","options":["due camicie bianca","due camicie bianchi","due camicie bianche"],"a":2,"note":"Both noun and adjective are feminine plural."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('legacy_quiz:9', 'legacy_quiz', NULL, 8, '{"q":"Complete: La banca è ___ farmacia. (opposite)","options":["di fronte alla","davanti la","a fronte della"],"a":0,"note":"Di fronte a + la becomes di fronte alla."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('legacy_quiz:10', 'legacy_quiz', NULL, 9, '{"q":"Which accepts an invitation warmly?","options":["Non mi va.","Magari un’altra volta.","Sì, volentieri!"],"a":2,"note":"Volentieri means gladly / with pleasure."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('legacy_quiz:11', 'legacy_quiz', NULL, 10, '{"q":"Complete: Ieri ___ un caffè.","options":["sono bevuto","ho bevuto","bevo"],"a":1,"note":"Bere takes avere; its past participle is bevuto."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('legacy_quiz:12', 'legacy_quiz', NULL, 11, '{"q":"Which asks whether bills are included?","options":["Le spese sono incluse?","Le camere sono spese?","È incluso il spendere?"],"a":0,"note":"Spese here means charges or bills."}');
