INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p01', 'preposition', NULL, 0, '{"id":"p01","before":"Vado","target":"cinema","hint":"a + il","answer":"al","full":"Vado al cinema."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p02', 'preposition', NULL, 1, '{"id":"p02","before":"Studio","target":"Biblioteca Centrale","hint":"in + la","answer":"nella","full":"Studio nella Biblioteca Centrale."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p03', 'preposition', NULL, 2, '{"id":"p03","before":"Il libro è","target":"tavolo","hint":"su + il","answer":"sul","full":"Il libro è sul tavolo."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p04', 'preposition', NULL, 3, '{"id":"p04","before":"La camera","target":"studenti","hint":"di + gli","answer":"degli","full":"La camera degli studenti."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p05', 'preposition', NULL, 4, '{"id":"p05","before":"Torniamo","target":"stazione","hint":"da + la","answer":"dalla","full":"Torniamo dalla stazione."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p06', 'preposition', NULL, 5, '{"id":"p06","before":"Le chiavi sono","target":"zaino","hint":"in + lo","answer":"nello","full":"Le chiavi sono nello zaino."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p07', 'preposition', NULL, 6, '{"id":"p07","before":"Andiamo","target":"amici","hint":"da + gli","answer":"dagli","full":"Andiamo dagli amici."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p08', 'preposition', NULL, 7, '{"id":"p08","before":"Parliamo","target":"vacanze","hint":"di + le","answer":"delle","full":"Parliamo delle vacanze."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p09', 'preposition', NULL, 8, '{"id":"p09","before":"Siamo","target":"hotel Leonardo","hint":"a + l’","answer":"all’","full":"Siamo all’hotel Leonardo."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p10', 'preposition', NULL, 9, '{"id":"p10","before":"Il quadro è","target":"parete","hint":"su + la","answer":"sulla","full":"Il quadro è sulla parete."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p11', 'preposition', NULL, 10, '{"id":"p11","before":"Abito","target":"centro","hint":"in (fixed general place)","answer":"in","full":"Abito in centro."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p12', 'preposition', NULL, 11, '{"id":"p12","before":"Vado","target":"casa","hint":"a (fixed expression)","answer":"a","full":"Vado a casa."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g01', 'exercise', 'c1w02', 0, '{"id":"g01","lessonId":"c1w02","skill":"grammar","type":"mcq","prompt":"Choose the correct nationality: Maria è…","answer":"italiana","explanation":"Nationality adjectives agree with the person described.","options":["italiano","italiana","italiane"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g02', 'exercise', 'c1w02', 1, '{"id":"g02","lessonId":"c1w02","skill":"grammar","type":"input","prompt":"Complete: Paul e John sono ingles__.","answer":"inglesi","explanation":"An adjective ending in -e becomes -i in the plural."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g03', 'exercise', 'c1w03', 2, '{"id":"g03","lessonId":"c1w03","skill":"grammar","type":"input","prompt":"Translate: I am twenty-five years old.","answer":"Ho venticinque anni.","explanation":"Italian expresses age with avere, not essere.","alternatives":["Ho 25 anni"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g04', 'exercise', 'c1w04', 3, '{"id":"g04","lessonId":"c1w04","skill":"grammar","type":"mcq","prompt":"Choose the article: ___ psicologo","answer":"uno psicologo","explanation":"Use uno before ps-, z-, gn- and s + consonant.","options":["un psicologo","uno psicologo","lo psicologo"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g05', 'exercise', 'c1w04', 4, '{"id":"g05","lessonId":"c1w04","skill":"grammar","type":"input","prompt":"Complete with fare: Io ___ l’ingegnere.","answer":"faccio","explanation":"Fare is irregular: io faccio."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g06', 'exercise', 'c1w07', 5, '{"id":"g06","lessonId":"c1w07","skill":"grammar","type":"mcq","prompt":"Choose: Mi ___ le città italiane.","answer":"piacciono","explanation":"The plural thing liked controls piacciono.","options":["piace","piacciono","piaci"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g07', 'exercise', 'c1w08', 6, '{"id":"g07","lessonId":"c1w08","skill":"grammar","type":"input","prompt":"Combine: in + la camera","answer":"nella camera","explanation":"In fuses with the definite article: in + la = nella."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g08', 'exercise', 'c1w11', 7, '{"id":"g08","lessonId":"c1w11","skill":"grammar","type":"input","prompt":"Conjugate svegliarsi for noi.","answer":"ci svegliamo","explanation":"The reflexive pronoun and verb must both agree with noi."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g09', 'exercise', 'c1w12', 8, '{"id":"g09","lessonId":"c1w12","skill":"grammar","type":"mcq","prompt":"Choose: ___ parlare italiano.","answer":"So parlare italiano.","explanation":"Sapere + infinitive means to know how to do something.","options":["So parlare italiano.","Conosco parlare italiano.","Conosco italiano parlare."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g10', 'exercise', 'c1w13', 9, '{"id":"g10","lessonId":"c1w13","skill":"grammar","type":"input","prompt":"Complete: Marta è ___ a casa. (tornare)","answer":"tornata","explanation":"With essere, the past participle agrees with Marta."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g11', 'exercise', 'c1w14', 10, '{"id":"g11","lessonId":"c1w14","skill":"grammar","type":"input","prompt":"Replace the object: Compro le mele.","answer":"Le compro.","explanation":"Le replaces a feminine plural direct object."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g12', 'exercise', 'c1w15', 11, '{"id":"g12","lessonId":"c1w15","skill":"grammar","type":"mcq","prompt":"Choose: Vorrei ___ pasta.","answer":"della pasta","explanation":"The feminine singular partitive is della.","options":["del pasta","della pasta","delle pasta"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g13', 'exercise', 'c1w16', 12, '{"id":"g13","lessonId":"c1w16","skill":"grammar","type":"mcq","prompt":"Choose the natural family phrase.","answer":"mia madre","explanation":"A singular, unmodified close family member normally omits the article.","options":["la mia madre","mia madre","il mio madre"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g14', 'exercise', 'c1w19', 13, '{"id":"g14","lessonId":"c1w19","skill":"grammar","type":"input","prompt":"Put in order: alzo / mi / sette / alle","answer":"Mi alzo alle sette.","explanation":"The reflexive pronoun goes before the conjugated verb.","alternatives":["mi alzo alle sette"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g15', 'exercise', 'c1w20', 14, '{"id":"g15","lessonId":"c1w20","skill":"grammar","type":"mcq","prompt":"Complete: Nell’appartamento ___ due camere.","answer":"ci sono","explanation":"Use ci sono with a plural noun.","options":["c’è","ci sono","sono ci"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g16', 'exercise', 'c2w07', 15, '{"id":"g16","lessonId":"c2w07","skill":"grammar","type":"input","prompt":"Combine: su + gli scaffali","answer":"sugli scaffali","explanation":"Su + gli becomes sugli."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g17', 'exercise', 'c2w08', 16, '{"id":"g17","lessonId":"c2w08","skill":"grammar","type":"input","prompt":"Make plural: la camicia bianca","answer":"le camicie bianche","explanation":"Both noun and adjective become feminine plural."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:g18', 'exercise', 'c2w09', 17, '{"id":"g18","lessonId":"c2w09","skill":"interaction","type":"mcq","prompt":"Choose the most appropriate formal hotel request.","answer":"Mi può aiutare?","explanation":"With hotel staff, formal Lei is appropriate.","options":["Mi può aiutare?","Mi aiuti tu?","Aiutami!"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:t01', 'exercise', 'c1w05', 18, '{"id":"t01","lessonId":"c1w05","skill":"writing","type":"input","prompt":"Translate: I would like a coffee and a croissant, please.","answer":"Vorrei un caffè e un cornetto, per favore.","explanation":"Vorrei is a useful polite default for ordering.","alternatives":["Vorrei un caffè e un cornetto per favore"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:t02', 'exercise', 'c1w06', 19, '{"id":"t02","lessonId":"c1w06","skill":"writing","type":"input","prompt":"Translate: In my free time I often read.","answer":"Nel tempo libero leggo spesso.","explanation":"Frequency adverbs commonly follow the conjugated verb."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:t03', 'exercise', 'c1w07', 20, '{"id":"t03","lessonId":"c1w07","skill":"writing","type":"input","prompt":"Translate: I don’t like sweets.","answer":"Non mi piacciono i dolci.","explanation":"Dolci is plural, so use piacciono."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:t04', 'exercise', 'c1w08', 21, '{"id":"t04","lessonId":"c1w08","skill":"writing","type":"input","prompt":"Translate: Is there a free room?","answer":"C’è una camera libera?","explanation":"C’è introduces one thing."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:t05', 'exercise', 'c1w12', 22, '{"id":"t05","lessonId":"c1w12","skill":"writing","type":"input","prompt":"Translate: I have to go to the pharmacy.","answer":"Devo andare in farmacia.","explanation":"A modal verb is followed directly by an infinitive."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:t06', 'exercise', 'c1w13', 23, '{"id":"t06","lessonId":"c1w13","skill":"writing","type":"input","prompt":"Translate: Yesterday we went to the market.","answer":"Ieri siamo andati al mercato.","explanation":"Andare uses essere in the passato prossimo.","alternatives":["Ieri siamo andate al mercato"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:t07', 'exercise', 'c1w15', 24, '{"id":"t07","lessonId":"c1w15","skill":"writing","type":"input","prompt":"Translate: I would like two hundred grams of ham.","answer":"Vorrei due etti di prosciutto.","explanation":"An etto is 100 grams; two etti are 200 grams."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:t08', 'exercise', 'c1w16', 25, '{"id":"t08","lessonId":"c1w16","skill":"writing","type":"input","prompt":"Translate: My brother is tall and friendly.","answer":"Mio fratello è alto e simpatico.","explanation":"The adjectives agree with the masculine singular noun."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:t09', 'exercise', 'c1w20', 26, '{"id":"t09","lessonId":"c1w20","skill":"writing","type":"input","prompt":"Translate: Are the bills included?","answer":"Le spese sono incluse?","explanation":"Spese means charges or bills in a rental context."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:t10', 'exercise', 'c2w09', 27, '{"id":"t10","lessonId":"c2w09","skill":"interaction","type":"input","prompt":"Politely refuse: I’m sorry, I already have plans.","answer":"Mi dispiace, ho già un impegno.","explanation":"This is a natural polite refusal."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:r01', 'exercise', 'c1w03', 28, '{"id":"r01","lessonId":"c1w03","skill":"grammar","type":"reorder","prompt":"Build a sentence meaning ‘I am 22 years old.’","answer":"Ho ventidue anni","explanation":"Italian uses avere for age.","options":["Ho","ventidue","anni"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:r02', 'exercise', 'c1w05', 29, '{"id":"r02","lessonId":"c1w05","skill":"interaction","type":"reorder","prompt":"Ask for the bill politely.","answer":"Il conto per favore","explanation":"This fixed phrase is enough in a restaurant.","options":["Il","conto","per","favore"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:r03', 'exercise', 'c1w07', 30, '{"id":"r03","lessonId":"c1w07","skill":"grammar","type":"reorder","prompt":"Build: ‘I like Italian cities.’","answer":"Mi piacciono le città italiane","explanation":"Piacciono agrees with le città.","options":["Mi","piacciono","le","città","italiane"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:r04', 'exercise', 'c1w12', 31, '{"id":"r04","lessonId":"c1w12","skill":"interaction","type":"reorder","prompt":"Ask where the station is.","answer":"Scusi dov’è la stazione","explanation":"Scusi politely gets someone’s attention.","options":["Scusi","dov’è","la","stazione"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:r05', 'exercise', 'c1w13', 32, '{"id":"r05","lessonId":"c1w13","skill":"grammar","type":"reorder","prompt":"Build: ‘Yesterday I ate pizza.’","answer":"Ieri ho mangiato la pizza","explanation":"Mangiare takes avere in the passato prossimo.","options":["Ieri","ho","mangiato","la","pizza"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:r06', 'exercise', 'c2w05', 33, '{"id":"r06","lessonId":"c2w05","skill":"interaction","type":"reorder","prompt":"Say the bank is opposite the pharmacy.","answer":"La banca è di fronte alla farmacia","explanation":"Di fronte a + la becomes di fronte alla.","options":["La","banca","è","di","fronte","alla","farmacia"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:r07', 'exercise', 'c2w09', 34, '{"id":"r07","lessonId":"c2w09","skill":"interaction","type":"reorder","prompt":"Suggest visiting a museum.","answer":"Ti va di visitare un museo","explanation":"Ti va di is followed by an infinitive.","options":["Ti","va","di","visitare","un","museo"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:l01', 'exercise', 'c1w02', 35, '{"id":"l01","lessonId":"c1w02","skill":"listening","type":"listen","prompt":"Write the sentence you hear.","answer":"Di dove sei?","explanation":"This asks where somebody is from.","audioText":"Di dove sei?"}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:l02', 'exercise', 'c1w05', 36, '{"id":"l02","lessonId":"c1w05","skill":"listening","type":"listen","prompt":"Write the sentence you hear.","answer":"Vorrei un caffè macchiato.","explanation":"Macchiato literally means marked, here with a little milk.","audioText":"Vorrei un caffè macchiato."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:l03', 'exercise', 'c1w07', 37, '{"id":"l03","lessonId":"c1w07","skill":"listening","type":"listen","prompt":"Write the sentence you hear.","answer":"Sono le otto e un quarto.","explanation":"This means it is quarter past eight.","audioText":"Sono le otto e un quarto."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:l04', 'exercise', 'c1w12', 38, '{"id":"l04","lessonId":"c1w12","skill":"listening","type":"listen","prompt":"Write the direction you hear.","answer":"Gira a destra al semaforo.","explanation":"Gira is the informal imperative of girare.","audioText":"Gira a destra al semaforo."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:l05', 'exercise', 'c1w15', 39, '{"id":"l05","lessonId":"c1w15","skill":"listening","type":"listen","prompt":"Write the sentence you hear.","answer":"Vorrei del pane e del formaggio.","explanation":"The partitive expresses an unspecified amount.","audioText":"Vorrei del pane e del formaggio."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:l06', 'exercise', 'c1w19', 40, '{"id":"l06","lessonId":"c1w19","skill":"listening","type":"listen","prompt":"Write the routine sentence you hear.","answer":"Di solito mi sveglio alle sette.","explanation":"Di solito means usually.","audioText":"Di solito mi sveglio alle sette."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:l07', 'exercise', 'c2w05', 41, '{"id":"l07","lessonId":"c2w05","skill":"listening","type":"listen","prompt":"Write the location sentence you hear.","answer":"Il museo è accanto alla banca.","explanation":"Accanto a + la becomes accanto alla.","audioText":"Il museo è accanto alla banca."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:l08', 'exercise', 'c2w09', 42, '{"id":"l08","lessonId":"c2w09","skill":"listening","type":"listen","prompt":"Write the hotel problem you hear.","answer":"La mia prenotazione non è nel sistema.","explanation":"Nel is in + il.","audioText":"La mia prenotazione non è nel sistema."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:c01', 'exercise', 'c1w11', 43, '{"id":"c01","lessonId":"c1w11","skill":"reading","type":"reading","prompt":"Why is today unusual?","answer":"It is Sofia’s birthday.","explanation":"The text contrasts the usual routine with a birthday breakfast.","passage":"Di solito Sofia si sveglia alle sette e fa una colazione veloce. Oggi, però, è il suo compleanno: la sua famiglia prepara una torta e le porta il caffè a letto.","options":["She is late for work.","It is Sofia’s birthday.","She does not like breakfast."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:c02', 'exercise', 'c1w13', 44, '{"id":"c02","lessonId":"c1w13","skill":"reading","type":"reading","prompt":"What did Luca do after lunch?","answer":"He visited a museum.","explanation":"Dopo pranzo introduces the later event.","passage":"Ieri Luca è andato a Firenze. La mattina ha visitato il mercato e ha comprato un regalo. Dopo pranzo è entrato in un museo. La sera è tornato a casa in treno.","options":["He bought a train.","He visited a museum.","He went to the market."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:c03', 'exercise', 'c1w20', 45, '{"id":"c03","lessonId":"c1w20","skill":"reading","type":"reading","prompt":"Which feature does the flat NOT have?","answer":"A garden.","explanation":"The advert lists a balcony, not a garden.","passage":"Affittasi appartamento luminoso vicino al centro. Ci sono una camera matrimoniale, un soggiorno, una cucina e un bagno. C’è anche un piccolo balcone. Le spese non sono incluse.","options":["A balcony.","A bathroom.","A garden."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:c04', 'exercise', 'c2w06', 46, '{"id":"c04","lessonId":"c2w06","skill":"reading","type":"reading","prompt":"What does Elena order as a main course?","answer":"Fish.","explanation":"Come secondo indicates the main course.","passage":"Elena prende una bruschetta come antipasto e il pesce come secondo. Da bere ordina dell’acqua naturale. Non prende il dolce perché è sazia.","options":["Pasta.","Fish.","Dessert."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:c05', 'exercise', 'c2w09', 47, '{"id":"c05","lessonId":"c2w09","skill":"reading","type":"reading","prompt":"Why can’t Marco enter his room?","answer":"The key card does not work.","explanation":"The first sentence states the practical problem.","passage":"Marco è davanti alla camera 214, ma la card non funziona. Torna alla reception e spiega il problema. La receptionist controlla il suo nome e prepara subito una nuova card.","options":["He forgot the room number.","The key card does not work.","The hotel has no rooms."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:s01', 'exercise', 'c2w01', 48, '{"id":"s01","lessonId":"c2w01","skill":"speaking","type":"speak","prompt":"Speak for 45–60 seconds: introduce yourself.","answer":"Mi chiamo… Sono… Vivo a… Studio/Lavoro… Nel tempo libero…","explanation":"A strong A1 introduction links five short facts.","hint":"Include name, nationality, home, work/study and one interest."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:s02', 'exercise', 'c2w02', 49, '{"id":"s02","lessonId":"c2w02","skill":"speaking","type":"speak","prompt":"Speak for one minute about your family.","answer":"Nella mia famiglia ci sono… Mio/Mia… si chiama…","explanation":"Use possessives, family words and two simple descriptions.","hint":"Mention at least three people and describe one person."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:s03', 'exercise', 'c1w19', 50, '{"id":"s03","lessonId":"c1w19","skill":"speaking","type":"speak","prompt":"Describe a normal weekday for one minute.","answer":"Di solito mi sveglio… Poi… Nel pomeriggio… La sera…","explanation":"Sequence a routine using reflexive verbs and times.","hint":"Use at least four reflexive verbs and two times."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:s04', 'exercise', 'c1w20', 51, '{"id":"s04","lessonId":"c1w20","skill":"speaking","type":"speak","prompt":"Describe your ideal home for 45–60 seconds.","answer":"La mia casa ideale è… Ci sono… C’è… Vorrei…","explanation":"Use c’è/ci sono, rooms and an adjective.","hint":"Mention location, three rooms and one special feature."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:s05', 'exercise', 'c2w09', 52, '{"id":"s05","lessonId":"c2w09","skill":"interaction","type":"speak","prompt":"Role-play: report a hotel problem using formal Lei.","answer":"Buongiorno, c’è un problema… Mi può aiutare?","explanation":"A successful interaction states the issue, gives details and requests action.","hint":"Choose Wi-Fi, booking, breakfast or a key-card problem."}');
